"""Read candidate files into clean text ready for the document."""

from __future__ import annotations

import json
import re
import unicodedata
from dataclasses import dataclass
from typing import List, Optional, Tuple

from . import languages
from .config import Config
from .scanner import (
    R_BINARY,
    R_EMPTY,
    R_GENERATED,
    R_MINIFIED,
    R_UNREADABLE,
    R_VENDORED,
    Candidate,
    ScanResult,
)

# Characters XML 1.0 forbids; a single one makes Word refuse to open the file.
_XML_INVALID = re.compile("[\x00-\x08\x0b\x0c\x0e-\x1f\ud800-\udfff￾￿]")

_GENERATED_MARKERS = re.compile(
    r"@generated|do not edit|auto-?generated|automatically generated|"
    r"generated by|code generated|this file was generated|webpackBootstrap",
    re.IGNORECASE,
)
# The marker only counts inside a comment, so SQL such as
# "GENERATED BY DEFAULT AS IDENTITY" is not mistaken for a generator banner.
_COMMENT_START = re.compile(r'''^\s*(#|//|/\*|\*|--|<!--|;|%|'|"""|rem\b|\{-|\(\*)''', re.IGNORECASE)


@dataclass
class SourceFile:
    rel: str
    language: str
    lexer: Optional[str]      # Pygments alias, None -> guess
    lines: List[str]          # tabs expanded, no newline characters
    total_lines: int          # before truncation
    omitted: Optional[Tuple[int, int]] = None  # (first omitted line no., count)
    encoding: str = "utf-8"


def decode(data: bytes) -> Tuple[str, str]:
    """Decode bytes, trying the encodings source files realistically use."""
    if data.startswith(b"\xef\xbb\xbf"):
        return data[3:].decode("utf-8", errors="replace"), "utf-8-sig"
    if data.startswith((b"\xff\xfe", b"\xfe\xff")):
        return data.decode("utf-16", errors="replace"), "utf-16"
    try:
        return data.decode("utf-8"), "utf-8"
    except UnicodeDecodeError:
        pass
    for enc in ("cp1258", "cp1252"):  # legacy Vietnamese / Western Windows
        try:
            # cp1258 stores tone marks as combining characters; compose them.
            return unicodedata.normalize("NFC", data.decode(enc)), enc
        except UnicodeDecodeError:
            continue
    return data.decode("latin-1"), "latin-1"


def looks_binary(data: bytes) -> bool:
    head = data[:8192]
    if b"\x00" in head and not head.startswith((b"\xff\xfe", b"\xfe\xff")):
        return True
    return False


def looks_minified(lines: List[str]) -> bool:
    if not lines:
        return False
    total = sum(len(line) for line in lines)
    longest = max(len(line) for line in lines)
    return longest > 1000 and total / len(lines) > 300


# Bundled third-party code keeps its "/*!" licence banner, e.g.
# "/*! Bootstrap v5.3.8 | MIT License */" or "/*! jQuery v3.7.1 ...".
_BANG_COMMENT = re.compile(r"/\*!")
_VERSION = re.compile(r"\bv?\d+\.\d+(\.\d+)?\b")
_LICENCE = re.compile(r"licen[cs]e|copyright|\(c\)|https?://", re.IGNORECASE)


def looks_vendored(lines: List[str]) -> bool:
    head = lines[:40]
    for i, line in enumerate(head):
        if _BANG_COMMENT.search(line):
            banner = "\n".join(head[i:i + 6])
            if _VERSION.search(banner) and _LICENCE.search(banner):
                return True
    return False


def looks_generated(lines: List[str]) -> bool:
    return any(
        _COMMENT_START.match(line) and _GENERATED_MARKERS.search(line)
        for line in lines[:10]
    )


def notebook_code(text: str) -> Tuple[str, Optional[str], str]:
    """Extract code cells from a Jupyter notebook.

    Returns ``(code, lexer alias, language name)``. Raises ValueError when the
    JSON is not a notebook.
    """
    nb = json.loads(text)
    if not isinstance(nb, dict) or "cells" not in nb:
        raise ValueError("not a notebook")
    meta = nb.get("metadata") or {}
    lang = (
        (meta.get("kernelspec") or {}).get("language")
        or (meta.get("language_info") or {}).get("name")
        or "python"
    ).lower()
    comment = "#" if lang in ("python", "r", "julia", "bash", "ruby") else "//"
    parts: List[str] = []
    n = 0
    for cell in nb.get("cells", []):
        if cell.get("cell_type") != "code":
            continue
        source = cell.get("source", "")
        if isinstance(source, list):
            source = "".join(source)
        if not source.strip():
            continue
        n += 1
        parts.append(f"{comment} [{n}]")
        parts.append(source.rstrip("\n"))
        parts.append("")
    return "\n".join(parts).rstrip("\n"), lang, f"Jupyter Notebook ({lang.capitalize()})"


def load(candidate: Candidate, cfg: Config) -> Tuple[Optional[SourceFile], Optional[str]]:
    """Return ``(SourceFile, None)`` or ``(None, skip reason)``."""
    try:
        data = candidate.path.read_bytes()
    except OSError:
        return None, R_UNREADABLE
    if looks_binary(data):
        return None, R_BINARY

    text, encoding = decode(data)
    info = languages.lookup(candidate.path.name)
    language, lexer = info if info else ("Text", "text")

    if candidate.rel.lower().endswith(".ipynb"):
        try:
            text, lexer, language = notebook_code(text)
        except (ValueError, AttributeError):
            pass  # malformed notebook: show the raw JSON

    text = _XML_INVALID.sub("", text.replace("\r\n", "\n").replace("\r", "\n"))
    lines = [line.rstrip().expandtabs(cfg.tab_size) for line in text.split("\n")]
    while lines and not lines[-1]:
        lines.pop()
    if not cfg.line_numbers:
        # With line numbers shown, leading blanks stay so numbering matches
        # the file on disk.
        while lines and not lines[0]:
            lines.pop(0)
    if not lines:
        return None, R_EMPTY

    if not candidate.explicit:
        if cfg.skip_minified and looks_minified(lines):
            return None, R_MINIFIED
        if cfg.skip_generated and looks_generated(lines):
            return None, R_GENERATED
        if cfg.default_excludes and looks_vendored(lines):
            return None, R_VENDORED

    if lexer is None:
        # Ambiguous extension (e.g. ".m"): let Pygments decide from the content.
        from .highlight import get_lexer

        guessed = get_lexer(None, candidate.path.name, "\n".join(lines[:200]))
        language = guessed.name
        lexer = guessed.aliases[0] if guessed.aliases else "text"

    src = SourceFile(
        rel=candidate.rel,
        language=language,
        lexer=lexer,
        lines=lines,
        total_lines=len(lines),
        encoding=encoding,
    )
    if cfg.max_lines and len(lines) > cfg.max_lines:
        head = (cfg.max_lines + 1) // 2
        tail = cfg.max_lines - head
        src.omitted = (head + 1, len(lines) - head - tail)
        src.lines = lines[:head] + lines[len(lines) - tail:] if tail else lines[:head]
    return src, None


def load_all(result: ScanResult, cfg: Config) -> List[SourceFile]:
    """Load every candidate; unreadable/generated ones move to ``skipped``."""
    out: List[SourceFile] = []
    for candidate in result.files:
        src, reason = load(candidate, cfg)
        if src is None:
            result.skipped.append((candidate.rel, reason or R_UNREADABLE))
        else:
            out.append(src)
    return out
